package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import java.math.*; @RestController @RequestMapping("/bill") public class BillController{private final BillService s;public BillController(BillService s){this.s=s;}@PostMapping public ResponseEntity<BillDTO> create(@Valid @RequestBody BillDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<BillDTO> all(){return s.all();}@GetMapping("/{id}") public BillDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public BillDTO update(@PathVariable Long id,@Valid @RequestBody BillDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/unpaid") public List<BillDTO> unpaid(){return s.unpaid();}@GetMapping("/patient/{id}/total") public BigDecimal total(@PathVariable Long id){return s.total(id);}}
